"""Prototype + self-test for math-verify structured-object comparison.

Covers: sets, intervals, unions, tuples, matrices, relations, And-chain vs
Interval, and the ``strict`` flag (canonical symbol renaming).

Run:  python /tmp/research/probe_grader_structures.py
"""

from __future__ import annotations

import itertools
import re

import sympy
from sympy import (
    Add,
    Basic,
    Complement,
    Eq,
    FiniteSet,
    Float,
    Intersection,
    Interval,
    MatrixBase,
    Mul,
    Rational,
    Set,
    Symbol,
    Tuple,
    Union,
)
from sympy.core.relational import Relational
from sympy.logic.boolalg import And as SympyAnd
from sympy.logic.boolalg import BooleanFunction, Or

from latex2sympy2_extended import NormalizationConfig, latex2sympy
from latex2sympy2_extended.latex2sympy2 import ConversionConfig

# ---------------------------------------------------------------------------
# parsing helper (mirrors math_verify's latex extraction path)
# ---------------------------------------------------------------------------
NC = NormalizationConfig(
    basic_latex=True, units=True, malformed_operators=True, nits=True, boxed="all", equations=False
)
CC = ConversionConfig(interpret_simple_eq_as_assignment=True)


def _strip_dollars(s: str) -> str:
    s = s.strip()
    for pat in (r"^\$\$(.*)\$\$$", r"^\\\[(.*)\\\]$", r"^\$(.*)\$$"):
        m = re.match(pat, s, re.S)
        if m:
            return m.group(1)
    return s


def L(s: str):
    """Parse one latex snippet the way math_verify's latex extractor would."""
    return latex2sympy(
        _strip_dollars(s), is_real=True, normalization_config=NC, conversion_config=CC
    )


# ===========================================================================
# 1. numeric leaf
# ===========================================================================
def _safe(fn, *a, **k):
    try:
        return fn(*a, **k)
    except Exception:
        return None


def _round(x, nd):
    """round a sympy number to ``nd`` decimal places, returning a Float or None."""
    try:
        if x.is_infinite or x.is_number is False:
            return None
        return sympy.Float(x, 30).round(nd)
    except Exception:
        return None


def _float_decimals(x):
    """decimals in the shortest round-trip repr of a Float (2.6667 -> 4)."""
    try:
        r = repr(float(x))
    except Exception:
        return None
    if "e" in r or "E" in r or "." not in r:
        return None
    return len(r.split(".")[1])


def sympy_numeric_eq(a, b, float_rounding: int, numeric_precision: int, rational_reconstruct=True):
    """Numeric leaf comparison used by every structured comparison below."""
    if not (isinstance(a, Basic) and isinstance(b, Basic)):
        return False
    if not (a.is_number and b.is_number):
        return False
    # rung 0: exact
    if a == b:
        return True
    # infinities
    if a.is_infinite or b.is_infinite:
        return bool(a == b)
    # rung 1: both rounded to `float_rounding` decimal places
    ra, rb = _round(a, float_rounding), _round(b, float_rounding)
    if ra is not None and rb is not None and ra == rb:
        return True
    # rung 2: high precision closeness (numeric_precision significant digits)
    d = _safe(lambda: abs((a - b).evalf(numeric_precision)))
    if d is not None and d.is_number and not d.is_infinite:
        try:
            if float(d) < 10.0 ** (-numeric_precision + 1):
                return True
        except Exception:
            pass
    # rung 3 (OPTIONAL): rational reconstruction -- one side is a decimal
    #                    approximation of the other's exact value.
    if rational_reconstruct:
        exact, flt = (a, b) if (b.is_Float and not a.is_Float) else (
            (b, a) if (a.is_Float and not b.is_Float) else (None, None)
        )
        if exact is not None:
            max_den = 10 ** max(1, float_rounding // 2)
            rr = _safe(lambda: Rational(repr(float(flt))).limit_denominator(max_den))
            if rr is not None and _safe(lambda: bool(sympy.simplify(exact - rr) == 0)):
                return True
    return False


# ===========================================================================
# 2. strict=False -- canonical symbol renaming
# ===========================================================================
def _iter_elements(expr):
    """Deterministic pre-order walk yielding sub-expressions."""
    if isinstance(expr, MatrixBase):
        for i in range(expr.rows):
            for j in range(expr.cols):
                yield from _iter_elements(expr[i, j])
        return
    if not isinstance(expr, Basic):
        return
    yield expr
    args = expr.args
    if isinstance(expr, FiniteSet):
        args = getattr(expr, "_unsorted_args", None) or expr.args
    for a in args:
        yield from _iter_elements(a)


def _ordered_free_symbols(expr):
    seen, out = set(), []
    for sub in _iter_elements(expr):
        if isinstance(sub, Symbol) and sub not in seen:
            seen.add(sub)
            out.append(sub)
    return out


def canonical_rename(expr):
    """Rename free symbols to _ms0, _ms1, ... by order of first appearance."""
    syms = _ordered_free_symbols(expr)
    if not syms:
        return expr
    mapping = {s: Symbol(f"_ms{i}") for i, s in enumerate(syms)}
    try:
        if isinstance(expr, MatrixBase):
            return expr.subs(mapping, simultaneous=True)
        return expr.subs(mapping, simultaneous=True)
    except Exception:
        return expr


# ===========================================================================
# 3. relations
# ===========================================================================
_FLIP = {">": "<", ">=": "<=", "<": ">", "<=": ">="}


def _rel_canonical(r):
    """(expr, op) with everything moved left and > / >= flipped to < / <=."""
    lhs, rhs, op = r.lhs, r.rhs, r.rel_op
    e = _safe(lambda: (lhs - rhs).doit())
    if e is None:
        return None
    if op in (">", ">="):
        e, op = -e, _FLIP[op]
    return (e, op)


def _proportional(e1, e2, positive_only: bool):
    """True when e1 == k*e2 for a nonzero constant k (k>0 if positive_only)."""
    if e1 == e2:
        return True
    if _safe(lambda: bool(sympy.simplify(sympy.expand(e1 - e2)) == 0)):
        return True
    if e2 == 0 or e1 == 0:
        return False
    k = _safe(lambda: sympy.simplify(sympy.expand(e1) / sympy.expand(e2)))
    if k is None or not getattr(k, "is_number", False) or k == 0:
        return False
    if positive_only:
        return bool(k.is_positive)
    return True


def sympy_compare_relational(gold, target, ctx):
    a, b = _rel_canonical(gold), _rel_canonical(target)
    if a is None or b is None:
        return False
    (ea, oa), (eb, ob) = a, b
    if oa != ob:
        return False
    return _proportional(ea, eb, positive_only=(oa in ("<", "<=")))


def _relation_as_set(x, allow_set_relation_comp: bool):
    """Convert a (compound) relation in one free symbol to a sympy Set."""
    if not isinstance(x, (Relational, BooleanFunction)):
        return None
    if isinstance(x, Eq) and not allow_set_relation_comp:
        # Eq(x, 5) -> {5} only when explicitly allowed
        return None
    if isinstance(x, Relational) and not allow_set_relation_comp:
        # a *single* inequality (x > 1) only when explicitly allowed;
        # compound chains (-793 < a < 10) are always allowed.
        return None
    if len(x.free_symbols) != 1:
        return None
    return _safe(lambda: x.as_set())


# ===========================================================================
# 4. containers: sets / intervals / tuples / matrices
# ===========================================================================
def _normalize_setop(s):
    """Re-evaluate the unevaluated Union/Intersection latex2sympy builds."""
    if isinstance(s, (Union, Intersection, Complement)):
        args = [_normalize_setop(a) for a in s.args]
        # rebuild with plain sympy FiniteSet so evaluation can merge them
        args = [FiniteSet(*a.args) if type(a).__name__ == "FiniteSet" else a for a in args]
        return _safe(lambda: type(s)(*args)) or s
    return s


def _unordered_match(gold_items, target_items, cmp):
    """Backtracking bipartite matching with a tolerant element comparator."""
    if len(gold_items) != len(target_items):
        return False
    n = len(gold_items)
    if n == 0:
        return True
    used = [False] * n

    def rec(i):
        if i == n:
            return True
        for j in range(n):
            if not used[j] and cmp(gold_items[i], target_items[j]):
                used[j] = True
                if rec(i + 1):
                    return True
                used[j] = False
        return False

    return rec(0)


def _ordered_items(x):
    """Positional view of an ordered container (Tuple, or FiniteSet as written)."""
    if isinstance(x, Tuple) or isinstance(x, (tuple, list)):
        return list(x)
    if isinstance(x, FiniteSet):
        return list(getattr(x, "_unsorted_args", None) or x.args)
    return None


def sympy_compare_sets(gold, target, ctx):
    """Structured comparison. Returns True/False/None (None = not applicable)."""
    cmp = lambda a, b: sympy_expr_eq(a, b, **ctx)  # noqa: E731

    g_tuple = isinstance(gold, Tuple)
    t_tuple = isinstance(target, Tuple)

    # --- matrices --------------------------------------------------------
    if isinstance(gold, MatrixBase) or isinstance(target, MatrixBase):
        if not (isinstance(gold, MatrixBase) and isinstance(target, MatrixBase)):
            return False
        if gold.shape != target.shape:
            return False
        return all(cmp(gold[i], target[i]) for i in range(len(gold)))

    # --- tuples (ordered) ------------------------------------------------
    if g_tuple or t_tuple:
        gi, ti = _ordered_items(gold), _ordered_items(target)
        if gi is None or ti is None:
            return False
        if len(gi) != len(ti):
            return False
        if all(cmp(a, b) for a, b in zip(gi, ti)):
            return True
        # a FiniteSet written against a Tuple may still match unordered
        if isinstance(gold, FiniteSet) or isinstance(target, FiniteSet):
            return _unordered_match(gi, ti, cmp)
        return False

    if not (isinstance(gold, Set) and isinstance(target, Set)):
        return None

    gold, target = _normalize_setop(gold), _normalize_setop(target)

    # --- intervals -------------------------------------------------------
    if isinstance(gold, Interval) or isinstance(target, Interval):
        if isinstance(gold, Interval) and isinstance(target, Interval):
            return (
                bool(gold.left_open) == bool(target.left_open)
                and bool(gold.right_open) == bool(target.right_open)
                and cmp(gold.start, target.start)
                and cmp(gold.end, target.end)
            )
        return False

    # --- finite sets (unordered) ----------------------------------------
    if isinstance(gold, FiniteSet) and isinstance(target, FiniteSet):
        return _unordered_match(list(gold.args), list(target.args), cmp)

    # --- set operations (Union / Intersection / Complement) --------------
    if type(gold).__name__ == type(target).__name__ and isinstance(
        gold, (Union, Intersection, Complement)
    ):
        return _unordered_match(list(gold.args), list(target.args), cmp)

    if gold.is_empty and target.is_empty:
        return True
    return False


# ===========================================================================
# 5. main ladder
# ===========================================================================
def sympy_expr_eq(
    gold,
    target,
    float_rounding: int = 6,
    numeric_precision: int = 15,
    allow_set_relation_comp: bool = False,
    strict: bool = True,
):
    ctx = dict(
        float_rounding=float_rounding,
        numeric_precision=numeric_precision,
        allow_set_relation_comp=allow_set_relation_comp,
        strict=True,  # renaming already applied at the top level
    )

    if not strict:
        gold, target = canonical_rename(gold), canonical_rename(target)

    if gold is target:
        return True
    if isinstance(gold, Basic) and isinstance(target, Basic):
        if type(gold) is type(target) and _safe(lambda: bool(gold == target)):
            return True
        # patched FiniteSet/And are subclasses -> compare by srepr of args too
        if type(gold).__name__ == type(target).__name__ and _safe(
            lambda: sympy.srepr(gold) == sympy.srepr(target)
        ):
            return True

    # --- relation vs set -------------------------------------------------
    is_bool = lambda x: isinstance(x, (Relational, BooleanFunction))  # noqa: E731
    if is_bool(gold) and isinstance(target, Set):
        s = _relation_as_set(gold, allow_set_relation_comp)
        if s is not None:
            return bool(sympy_compare_sets(s, target, ctx))
        return False
    if isinstance(gold, Set) and is_bool(target):
        s = _relation_as_set(target, allow_set_relation_comp)
        if s is not None:
            return bool(sympy_compare_sets(gold, s, ctx))
        return False

    # --- relation vs relation -------------------------------------------
    if is_bool(gold) or is_bool(target):
        if isinstance(gold, Relational) and isinstance(target, Relational):
            return sympy_compare_relational(gold, target, ctx)
        if isinstance(gold, (SympyAnd, Or)) and isinstance(target, (SympyAnd, Or)):
            if type(gold).__name__ != type(target).__name__:
                return False
            ga = list(getattr(gold, "_unsorted_args", None) or gold.args)
            ta = list(getattr(target, "_unsorted_args", None) or target.args)
            cmp = lambda a, b: sympy_expr_eq(a, b, **ctx)  # noqa: E731
            if _unordered_match(ga, ta, cmp):
                return True
            # fall back to set semantics for single-variable chains
            gs = _safe(lambda: gold.as_set())
            ts = _safe(lambda: target.as_set())
            if gs is not None and ts is not None:
                return bool(sympy_compare_sets(gs, ts, ctx))
            return False
        return False

    # --- containers ------------------------------------------------------
    r = sympy_compare_sets(gold, target, ctx)
    if r is not None:
        return bool(r)
    if isinstance(gold, (Set, MatrixBase, Tuple)) != isinstance(
        target, (Set, MatrixBase, Tuple)
    ):
        return False

    # --- numbers ---------------------------------------------------------
    if sympy_numeric_eq(gold, target, float_rounding, numeric_precision):
        return True

    # --- symbolic --------------------------------------------------------
    if isinstance(gold, Basic) and isinstance(target, Basic):
        if _safe(lambda: bool(sympy.simplify(sympy.expand(gold - target)) == 0)):
            return True
    return False


def verify_latex(gold: str, target: str, precision: int = 6, strict: bool = True,
                 allow_set_relation_comp: bool = False):
    g, t = L(gold), L(target)
    return sympy_expr_eq(
        g, t, float_rounding=precision, strict=strict,
        allow_set_relation_comp=allow_set_relation_comp,
    )


# ===========================================================================
# self-test
# ===========================================================================
PMAT_GOLD = r"$\begin{pmatrix} x & y \\ z & w \end{pmatrix}$"
PMAT_PRED = r"$\begin{pmatrix} a & b \\ c & {d} \end{pmatrix}$"  # {d} works around lexer bug

CASES = [
    # --- sets / intervals -------------------------------------------------
    ("SET", r"${1,3}\cup{2,4}$", r"${1,2,3,4}$", True, 6, True),
    ("SET", r"${1,2,3}$", r"${3,2,1}$", True, 6, True),
    ("SET", r"$[0,1)$", r"$[0,1)$", True, 6, True),
    ("SET", r"$[0,9)$", r"$[0,1)$", False, 6, True),
    ("SET", r"$(0,9)$", r"$[0,9)$", False, 6, True),
    ("SET", r"$(\frac{3}{5},\frac{8}{3}]$", r"$(0.6,2.6667]$", True, 2, True),
    ("SET", r"$(\frac{3}{5},\frac{8}{3}]$", r"$(0.6,2.6667]$", True, 6, True),
    ("SET", r"$[0,1)$", r"$(0, 1)$", False, 6, True),  # "the domain is (0,1)"
    ("SET", r"$z \in \left[-\frac{3}{2},-1\right]\cup\left[1,\frac{3}{2}\right]$",
     r"$[-1.5,-1]\cup[1,1.5]$", True, 6, True),
    ("SET", r"${1,2,3}$", r"${1,2,4}$", False, 6, True),
    # --- tuples -----------------------------------------------------------
    ("TUP", r"$(1,\frac{9}{2})$", r"$(1,4.5)$", True, 6, True),
    ("TUP", r"$(7,6)$", r"$(7,6)$", True, 6, True),
    ("TUP", r"$(7,6)$", r"$(6,7)$", False, 6, True),
    # --- matrices ---------------------------------------------------------
    ("MAT", r"$\begin{pmatrix}\frac{1}{3}\\ \frac{1}{5} \end{pmatrix}$",
     r"$\begin{pmatrix}0.33\\0.2 \end{pmatrix}$", True, 2, True),
    ("MAT", r"$(\begin{pmatrix}\frac{1}{3}\\ \frac{1}{5} \end{pmatrix})$",
     r"$\begin{pmatrix}0.33\\0.2 \end{pmatrix}$", True, 2, True),
    ("MAT", "\\boxed{\n\\begin{pmatrix} 0 & 3 \\\\ 0 & -1 \\end{pmatrix}\n}",
     "\\boxed{\n\\begin{pmatrix} 0 & 3 \\\\ 0 & -1 \\end{pmatrix}\n}", True, 6, True),
    ("MAT", r"$\begin{pmatrix} 1 & 0 \\ 0 & 1 \end{pmatrix}$",
     r"$\begin{pmatrix} 1 & 0 \\ 0 & 2 \end{pmatrix}$", False, 6, True),
    ("MAT", r"$\begin{pmatrix} 1 & 0 \end{pmatrix}$",
     r"$\begin{pmatrix} 1 \\ 0 \end{pmatrix}$", False, 6, True),
    # --- relations --------------------------------------------------------
    ("REL", r"$x \geq 5$", r"$5 \leq x$", True, 6, True),
    ("REL", r"$x \geq 5$", r"$5 \geq x$", False, 6, True),
    ("REL", r"$34x+45y-20z+100=0$", r"$-34x-45y+20z-100=0$", True, 6, True),
    ("REL", r"$34x+45y-20z+100=0$", r"$34x+45y-20z-100=0$", False, 6, True),
    ("REL", r"$$-793 < a < 10$$", r"$$(-793, 10)$$", True, 6, True),
    ("REL", r"$$-793 < a < 10$$", r"$$[-793, 10]$$", False, 6, True),
    ("REL", r"$$-793 < a < 10$$", r"$$-793 < b < 10$$", True, 6, True),
    # single relation vs interval is gated by allow_set_relation_comp
    ("REL", r"$x > 1$", r"$(1,\infty)$", False, 6, True),
    # --- strict -----------------------------------------------------------
    ("STRICT", r"$f(x)$", r"$f(y)$", False, 6, True),
    ("STRICT", r"$f(x)$", r"$f(y)$", True, 6, False),
    ("STRICT", r"$\sin(x)+\cos(x)$", r"$\sin(t)+\cos(t)$", False, 6, True),
    ("STRICT", r"$\sin(x)+\cos(x)$", r"$\sin(t)+\cos(t)$", True, 6, False),
    ("STRICT", PMAT_GOLD, PMAT_PRED, False, 6, True),
    ("STRICT", PMAT_GOLD, PMAT_PRED, True, 6, False),
    ("STRICT", r"$g(a, b) + h(a)$", r"$g(x, y) + h(x)$", False, 6, True),
    ("STRICT", r"$g(a, b) + h(a)$", r"$g(x, y) + h(x)$", True, 6, False),
    ("STRICT", r"$\frac{1}{3}$", r"$0.333333$", True, 6, True),
    ("STRICT", r"$x+1$", r"$y+2$", False, 6, False),  # renaming must not over-match
    ("STRICT", r"$g(a,b)+h(a)$", r"$g(x,y)+h(y)$", False, 6, False),
]

EXTRA = [
    # allow_set_relation_comp=True opens up the single-relation case
    ("FLAG", r"$x > 1$", r"$(1,\infty)$", True, 6, True, True),
]


def main():
    npass = nfail = 0
    fails = []
    for kind, gold, pred, expected, prec, strict in CASES:
        try:
            got = verify_latex(gold, pred, precision=prec, strict=strict)
        except Exception as e:  # noqa: BLE001
            got = f"ERR {type(e).__name__}: {e}"
        ok = got is expected
        npass += ok
        nfail += not ok
        status = "ok  " if ok else "FAIL"
        if not ok:
            fails.append((kind, gold, pred, prec, strict, expected, got))
        print(f"[{status}] {kind:6s} prec={prec} strict={strict!s:5s} "
              f"exp={expected!s:5s} got={got!s:5s}  {gold[:38]!r} vs {pred[:38]!r}")
    for kind, gold, pred, expected, prec, strict, asrc in EXTRA:
        got = verify_latex(gold, pred, precision=prec, strict=strict, allow_set_relation_comp=asrc)
        ok = got is expected
        npass += ok
        nfail += not ok
        print(f"[{'ok  ' if ok else 'FAIL'}] {kind:6s} allow_set_rel={asrc} "
              f"exp={expected} got={got}  {gold!r} vs {pred!r}")
    print(f"\n{npass}/{npass + nfail} cases pass")
    for f in fails:
        print("  FAILED:", f)


if __name__ == "__main__":
    main()

