# ===========================================================================
# 2. strict=False -- canonical symbol renaming
# ===========================================================================
_COMMUTATIVE = (Add, Mul, FiniteSet, SympyAnd, Or, Union, Intersection)


def _blind_key(e):
    """Name-blind structural signature: every Symbol collapses to "S"."""
    if isinstance(e, Symbol):
        return "S"
    if not isinstance(e, Basic) or not e.args:
        return f"{type(e).__name__}:{e}"
    kids = [_blind_key(a) for a in e.args]
    if isinstance(e, _COMMUTATIVE):
        kids = sorted(kids)
    return f"{type(e).__name__}({','.join(kids)})"


def _iter_elements(expr):
    """Deterministic, name-blind pre-order walk yielding sub-expressions.

    Args of commutative operators are visited in name-blind structural order so
    that the resulting symbol numbering does not depend on the symbol names.
    """
    if isinstance(expr, MatrixBase):
        for i in range(expr.rows):
            for j in range(expr.cols):
